'use strict';
// Reproduces the user's 38-step Default Scene; physical identifiers are anonymized.
const sources=['Desktop','Browser','Voice','Music','Microphone'],targets=['Chat Mic','Speakers','Headphones'];
const operations=[...['A','B'].map(mix=>({type:'sourceMute',sources,mix,state:'unmuted'})),{type:'sourceVolumeLink',sources,state:'unlinked'},{type:'sourceVolume',sources,mix:'A',volume:100},{type:'sourceVolume',sources:sources.filter(n=>n!=='Music'),mix:'B',volume:100},{type:'sourceVolume',sources:['Music'],mix:'B',volume:70},{type:'targetMute',targets:['Chat Mic','Speakers'],state:'unmuted'},{type:'targetMute',targets:['Headphones'],state:'muted'},{type:'targetVolume',targets,volume:100},{type:'targetMix',targets:['Chat Mic','Speakers'],mix:'A'},{type:'targetMix',targets:['Headphones'],mix:'B'}];
for(const s of sources){operations.push({type:'route',sources:[s],targets:s==='Microphone'?['Chat Mic']:['Speakers','Headphones'],state:'on'},{type:'route',sources:[s],targets:s==='Microphone'?['Speakers','Headphones']:['Chat Mic'],state:'off'})}
const inputs=['Webcam','Volt 2 input','Controller input'].map((name,i)=>({id:'input-'+i,name})),outputs=['Volt 2 output','Desktop speakers','Controller output'].map((name,i)=>({id:'output-'+i,name}));
for(const [type,devices] of [['physicalInput',inputs],['physicalOutput',outputs]])for(const [i,device] of devices.entries()){operations.push({type:type+'Mute',device,state:'unmuted'},{type:type+'Volume',device,volume:i===2?0:100})}
operations.push({type:'defaultDevice',deviceType:'input',device:inputs[1]},{type:'defaultDevice',deviceType:'output',device:outputs[1]});
const applications=[{deviceType:'Source',name:'Spotify',process:'spotify'}];operations.push({type:'applicationMute',applications,state:'unmuted'},{type:'applicationVolume',applications,volume:100},{type:'applicationRoute',applications,state:'on',targetName:'Music'});
function status(){return {audio:{profile:{audio_node_quantum:null,devices:{sources:{virtual_devices:sources.map((name,i)=>({id:'s'+i,name,volumes:{volume:{A:40,B:30},volumes_linked:0.75},mute_states:{mute_state:['TargetA','TargetB'],mute_targets:{TargetA:[],TargetB:[]}}}))},targets:{virtual_devices:targets.map((name,i)=>({id:'t'+i,name,volume:50,muted:false,mix:'A'}))}},routes:Object.fromEntries(sources.map((_,i)=>['s'+i,[]]))},devices:{Source:inputs.map(x=>({...x,volume:50,muted:true})),Target:outputs.map(x=>({...x,volume:50,muted:true}))},defaults_id:{Source:'input-0',Target:'output-0'},applications:{Source:{spotify:{Spotify:[{node_id:42,volume:50,muted:true,target_id:null}]}}}}}
}
module.exports={scene:{format:'WeaverDeckScene',formatVersion:1,name:'Default Scene',sceneVersion:1,operations},status};
